mapper.select:
SELECT id, document_id, redis_op_id, client_update_id, update_data, operator_id, operator_type, create_time
FROM document_op_log
WHERE document_id = #{documentId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM document_op_log
WHERE document_id = #{documentId}
  AND id > #{afterId}

mapper.delete:
DELETE FROM document_op_log
WHERE document_id = #{documentId}
  AND id <= #{throughId}
